/// 学習時と同じ正規化 + Linear(35→64) → ReLU → Linear(64→32) → ReLU
/// → Linear(32→1) の forward pass。返すのは**ロジット**
pub fn occupancy_logit(features: &[f64; BELIEF_FEATURES]) -> f64 {
    let mut x = [0.0f64; BELIEF_FEATURES];
    for i in 0..BELIEF_FEATURES {
        x[i] = (features[i] - BELIEF_NN_MEAN[i]) / BELIEF_NN_STD[i];
    }
    let mut h1 = [0.0f64; 64];
    for j in 0..64 {
        let mut s = BELIEF_NN_B1[j];
        for i in 0..BELIEF_FEATURES {
            s += BELIEF_NN_W1[j][i] * x[i];
        }
        h1[j] = s.max(0.0);
    }
    let mut h2 = [0.0f64; 32];
    for j in 0..32 {
        let mut s = BELIEF_NN_B2[j];
        for i in 0..64 {
            s += BELIEF_NN_W2[j][i] * h1[i];
        }
        h2[j] = s.max(0.0);
    }
    let mut out = BELIEF_NN_B3;
    for i in 0..32 {
        out += BELIEF_NN_W3[i] * h2[i];
    }
    // 分布外入力への安全弁（opp_move_nn の clamp と同じ趣旨）。
    // ロジット ±12 は確率 6e-6 〜 1-6e-6 に相当し、実運用の範囲は覆う
    out.clamp(-12.0, 12.0)
}

/// 占有確率（[0,1]）
pub fn occupancy(features: &[f64; BELIEF_FEATURES]) -> f64 {
    1.0 / (1.0 + (-occupancy_logit(features)).exp())
}

/// 盤面ぶんの占有確率。自駒のマスは 0（相手の駒は居ない）
pub fn board_occupancy(ctx: &BeliefContext) -> [f64; 81] {
    let mut out = [0.0f64; 81];
    for sq in all_squares() {
        if ctx.is_mine(sq) {
            continue;
        }
        out[sq_index(sq)] = occupancy(&ctx.features(sq));
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::belief_features::BELIEF_FEATURE_NAMES;
    use crate::observation::ObservationLog;
    use crate::protocol::Color;

    fn case(pairs: &[(&str, f64)]) -> [f64; BELIEF_FEATURES] {
        let mut f = [0.0f64; BELIEF_FEATURES];
        for &(name, v) in pairs {
            let i = BELIEF_FEATURE_NAMES
                .iter()
                .position(|&n| n == name)
                .unwrap_or_else(|| panic!("未知の特徴量名: {name}"));
            f[i] = v;
        }
        f
    }

    /// プレースホルダ（ゼロ重み）のまま誤ってマージする事故のガード
    /// （value_nn / opp_move_nn と同じ）
    #[test]
    fn weights_are_not_placeholder_zeros() {
        assert!(
            BELIEF_NN_W1.iter().flatten().any(|&w| w != 0.0),
            "W1が全ゼロ = export_belief_weights.py 未実行のプレースホルダ"
        );
        assert!(BELIEF_NN_W2.iter().flatten().any(|&w| w != 0.0));
        assert!(BELIEF_NN_W3.iter().any(|&w| w != 0.0));
    }

    /// numpy側で同じ定数（このファイルのAUTO-GENERATED区間）を独立に読み直して
    /// 計算した値との突き合わせ（行列の転置・インデックス取り違えの検出用）。
    /// 期待値の再生成は scratchpad の belief_crosscheck.py。
    /// **重みを差し替えたら必ず再生成すること**
    #[test]
    fn matches_numpy_cross_check() {
        let home_pawn = case(&[
            ("prior_occ", 0.25),
            ("opp_board_n", 1.0),
            ("opp_moves_n", 0.1),
            ("depth_opp", 0.25),
            ("file_center", 1.0),
            ("init_opp", 1.0),
            ("init_pawn", 1.0),
            ("untouched", 1.0),
            ("dist_my_king", 0.75),
            ("dist_opp_last", 1.0),
            ("king_cand_frac", 0.05),
        ]);
        let drop_foul = case(&[
            ("prior_occ", 0.24),
            ("opp_board_n", 0.9),
            ("opp_taken_n", 0.2),
            ("opp_moves_n", 0.5),
            ("depth_opp", 0.625),
            ("file_center", 0.75),
            ("drop_foul", 0.3333),
            ("drop_foul_rec", 1.0),
            ("dist_my_king", 0.375),
            ("dist_opp_last", 0.5),
        ]);
        let just_empty = case(&[
            ("prior_occ", 0.24),
            ("opp_board_n", 0.9),
            ("opp_moves_n", 0.5),
            ("depth_opp", 0.5),
            ("file_center", 0.5),
            ("empty_seen", 1.0),
            ("empty_seen_rec", 1.0),
            ("my_attack", 0.6667),
            ("dist_my_king", 0.5),
            ("dist_opp_last", 0.625),
        ]);
        let cases: [([f64; BELIEF_FEATURES], f64); 4] = [
            ([0.0; BELIEF_FEATURES], 0.0042755978593237084),
            (home_pawn, 0.8043776477687651),
            (drop_foul, 0.9800994119839938),
            (just_empty, 0.0009618785269105713),
        ];
        for (features, expected) in cases {
            let got = occupancy(&features);
            assert!(
                (got - expected).abs() < 1e-9,
                "got={got} expected={expected}"
            );
        }
    }

    /// 分布外入力でも確率として有界（clamp + sigmoid）
    #[test]
    fn output_is_bounded() {
        for f in [[1e6f64; BELIEF_FEATURES], [-1e6f64; BELIEF_FEATURES]] {
            let p = occupancy(&f);
            assert!((0.0..=1.0).contains(&p), "出力が[0,1]を外れた: {p}");
        }
    }

    /// 初期局面: 相手の初期配置マスは高く、自陣側の空きマスは低い
    #[test]
    fn initial_position_belief_is_sane() {
        let ctx = BeliefContext::from_log(Color::Sente, &ObservationLog::default());
        let occ = board_occupancy(&ctx);
        let at = |s: &str| occ[sq_index(crate::board::parse_usi_square(s).unwrap())];
        assert!(at("5a") > 0.5, "相手玉の初期マスが低すぎる: {}", at("5a"));
        assert!(at("8b") > 0.5, "相手飛車の初期マスが低すぎる: {}", at("8b"));
        assert!(at("5e") < 0.2, "中央の空きマスが高すぎる: {}", at("5e"));
        // 自駒のマスは 0
        assert_eq!(at("7g"), 0.0);
    }
}
